INSERT IGNORE INTO products (sku, name, category_id, brand, unit_of_measure, cost_price, selling_price, tax_rate_id, reorder_level, track_batches, track_expiry, allow_price_override, active, created_at, updated_at, version) SELECT 'PONDS-MAGIC-100G', 'Pond''s Magic Freshness Talc Acacia Honey 100g', c.id, 'Pond''s', 'EACH', 240.0000, 300.00, t.id, 5, FALSE, FALSE, FALSE, TRUE, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), 0 FROM categories c, tax_rates t WHERE c.code = 'PERS' AND t.code = 'VAT_STD';
INSERT IGNORE INTO product_barcodes (product_id, barcode, barcode_type, is_primary, created_at) SELECT id, '4792081468713', 'EAN_13', TRUE, UTC_TIMESTAMP(6) FROM products WHERE sku = 'PONDS-MAGIC-100G';
INSERT INTO stock_movements (store_id, product_id, batch_id, movement_type, quantity_change, quantity_before, quantity_after, unit_cost, reference_type, reference_id, reference_line_id, reason, performed_by, created_at) SELECT (SELECT id FROM stores WHERE code = 'CMB01'), (SELECT id FROM products WHERE sku = 'PONDS-MAGIC-100G'), NULL, 'OPENING_BALANCE', 30, 0, 30, 240.0000, 'OPENING_STOCK', NULL, NULL, 'Opening stock', (SELECT id FROM users WHERE username = 'admin'), UTC_TIMESTAMP(6) FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM inventory_balances b WHERE b.store_id = (SELECT id FROM stores WHERE code = 'CMB01') AND b.product_id = (SELECT id FROM products WHERE sku = 'PONDS-MAGIC-100G'));
INSERT INTO inventory_balances (store_id, product_id, quantity_on_hand, average_cost, last_movement_at, version) SELECT (SELECT id FROM stores WHERE code = 'CMB01'), (SELECT id FROM products WHERE sku = 'PONDS-MAGIC-100G'), 30, 240.0000, UTC_TIMESTAMP(6), 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM inventory_balances b WHERE b.store_id = (SELECT id FROM stores WHERE code = 'CMB01') AND b.product_id = (SELECT id FROM products WHERE sku = 'PONDS-MAGIC-100G'));
